// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human sees and opens drafts"
// Changes: The client project session opened on a draft (fake transport, fake timers): the draft's parts over the
//          project's export naming and simulation inputs, recorded as viewed by the human.

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { defaultProjectData, type ProjectData } from './project'
import { createProjectSession } from './projectSession'
import { createFakeTransport } from './projectTransport.fake'
import type { ProjectRecord } from '#/server/projects.server'

const project = (): ProjectRecord => ({
  id: 'p1',
  name: 'Výrazy',
  data: {
    ...defaultProjectData(),
    def: { nonterminals: 'E', terminals: 'id +', start: 'E' },
    ll: { grammar: 'E -> id', input: 'id + id' },
    prec: { terminals: ['+', 'id'], cells: {}, rules: 'E -> id', input: 'id' },
    names: { map: 'id ID', ntPrefix: 'N_', tPrefix: 'T_', precPrefix: 'P_' },
  },
  revision: 3,
  createdAt: '2026-01-01T00:00:00.000Z',
  updatedAt: '2026-01-01T00:00:00.000Z',
  view: { llSim: { step: 2, speed: 1 } },
})

// An agent forks a draft and rewrites its grammar rules; the human then opens it.
async function openDraft() {
  const fake = createFakeTransport(project())
  const draft = fake.createDraft('Oprava konfliktu')
  fake.agentEdit(draft.id, { grammarRules: 'E -> id\nE -> id + E' })
  const opening = await fake.transport.loadDraft({ draftId: draft.id })
  const session = createProjectSession(opening!, fake.transport)
  return { fake, draft, session, state: () => session.getState() }
}

beforeEach(() => vi.useFakeTimers())
afterEach(() => vi.useRealTimers())

describe('opening a draft', () => {
  it("shows the draft's parts with the project's export naming and simulation inputs", async () => {
    const { state } = await openDraft()
    const expected: ProjectData = { ...project().data, ll: { grammar: 'E -> id\nE -> id + E', input: 'id + id' } }
    expect(state().data).toEqual(expected)
    expect(state().draft).toMatchObject({ label: 'Oprava konfliktu', state: 'open', revision: 2 })
  })

  it('a project session has no draft and is editable', () => {
    const fake = createFakeTransport(project())
    const session = createProjectSession(project(), fake.transport)
    expect(session.getState()).toMatchObject({ draft: null, readOnly: false })
  })

  it('loading an unknown draft finds nothing', async () => {
    const fake = createFakeTransport(project())
    expect(await fake.transport.loadDraft({ draftId: 'nope' })).toBeNull()
  })

  it('showing the draft records it as viewed by the human at its current revision', async () => {
    const { fake, draft, session } = await openDraft()
    expect(fake.draft(draft.id)?.humanViewedRevision).toBe(0)

    session.resume()
    await vi.advanceTimersByTimeAsync(0)

    expect(fake.callsOf('markDraftViewed')).toHaveLength(1)
    expect(fake.draft(draft.id)?.humanViewedRevision).toBe(2)
  })

  it('a project session records no draft as viewed', async () => {
    const fake = createFakeTransport(project())
    createProjectSession(project(), fake.transport).resume()
    await vi.advanceTimersByTimeAsync(0)
    expect(fake.callsOf('markDraftViewed')).toHaveLength(0)
  })
})

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Human edits drafts"
// Changes: Drafts are editable now (see draftEditing.test.ts); the view state stays the project's.
describe("a draft's view state", () => {
  it("stepping the LL simulation is the project's view state and is still saved", async () => {
    const { fake, session } = await openDraft()
    session.updateView((v) => ({ ...v, llSim: { ...v.llSim, step: 5 } }))
    await vi.advanceTimersByTimeAsync(600)
    expect(fake.server.view.llSim.step).toBe(5)
  })
})
